#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
中国野生动物分布地图 · 版本存档 v2（web_2.py）
================================================
本文件为自包含存档：内嵌了当前版本的核心文件
（index.html + css/tailwind.css + data/animals.json），
不依赖外部文件即可还原或预览。

用法:
    python3 web_2.py               # 启动本地预览服务器（内嵌数据，无需磁盘文件）
    python3 web_2.py --restore     # 将内嵌文件还原到当前目录（同名覆盖）
    python3 web_2.py --check       # 校验存档完整性

存档时间: 2026-08-03 22:55:37
文件清单: index.html, css/tailwind.css, data/animals.json, data/100000_full.json
"""
import argparse
import base64
import pathlib
import sys
import zlib
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from functools import partial

# ==== 内嵌数据（zlib 压缩 + base64） ====
EMBEDDED = {
    "index.html": "",
    "css/tailwind.css": "",
    "data/animals.json": "",
    "data/100000_full.json": "",
}

def decode(name):
    return zlib.decompress(base64.b64decode(EMBEDDED[name])).decode("utf-8")

def do_restore(dest):
    dest = pathlib.Path(dest).resolve()
    for name in EMBEDDED:
        path = dest / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(decode(name), encoding="utf-8")
        print("  还原 %s (%d KB)" % (name, path.stat().st_size // 1024))
    print("完成。目录: %s" % dest)

def do_check():
    ok = True
    for name, data in EMBEDDED.items():
        try:
            text = decode(name)
            if not text.strip():
                print("  空内容: %s" % name); ok = False
        except Exception as e:
            print("  损坏: %s (%s)" % (name, e)); ok = False
    print("存档校验: " + ("通过" if ok else "失败"))
    return ok

def serve():
    files = {name: decode(name) for name in EMBEDDED}
    class Handler(SimpleHTTPRequestHandler):
        def __init__(self, *a, **kw):
            super().__init__(*a, directory=str(pathlib.Path.cwd()), **kw)
        def do_GET(self):
            path = self.path.split("?")[0].lstrip("/") or "index.html"
            if path in files:
                body = files[path].encode("utf-8")
                ctype = "text/html; charset=utf-8"
                if path.endswith(".css"): ctype = "text/css; charset=utf-8"
                elif path.endswith(".json"): ctype = "application/json; charset=utf-8"
                self.send_response(200)
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
            super().do_GET()
        def log_message(self, fmt, *args):
            sys.stdout.write("[%s] %s\n" % (self.log_date_time_string(), fmt % args))
    port = 8080
    httpd = None
    for p in range(port, port + 20):
        try:
            httpd = ThreadingHTTPServer(("127.0.0.1", p), Handler)
            port = p; break
        except OSError:
            continue
    if not httpd:
        print("端口 %d-%d 均被占用" % (port, port + 19)); sys.exit(1)
    url = "http://localhost:%d/" % port
    print("=" * 50)
    print("  野生动物分布地图 · 存档 v2 预览")
    print("  访问地址: %s" % url)
    print("  按 Ctrl+C 停止")
    print("=" * 50)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\n已停止。")
        httpd.server_close()

def main():
    ap = argparse.ArgumentParser(description="野生动物分布地图版本存档 v2")
    ap.add_argument("--restore", nargs="?", const=".", default=None,
                    help="还原文件到指定目录（默认当前目录）")
    ap.add_argument("--check", action="store_true", help="校验存档完整性")
    ap.add_argument("--serve", action="store_true", help="启动内嵌预览服务器")
    args = ap.parse_args()
    if args.check: sys.exit(0 if do_check() else 1)
    if args.restore is not None: do_restore(args.restore); return
    if args.serve: serve(); return
    serve()

if __name__ == "__main__":
    main()
